def hidden_rule_fn(state):
    # For each particle, find the nearest particle of a different type (by krelon_dist)
    # Move by (sign(dx), sign(dy)) toward that particle
    # VEXON uses the negative of (sign(dx), sign(dy))
    # In 2-type scenarios, the winner stays and the loser moves

    def toroidal_diff(a, b, size=8):
        d = (b - a) % size
        if d > size // 2:
            d -= size
        return d

    def sign(x):
        if x > 0:
            return 1
        elif x < 0:
            return -1
        else:
            return 0

    def krelon_dist(p, q):
        dx = toroidal_diff(p['x'], q['x'])
        dy = toroidal_diff(p['y'], q['y'])
        if p['type'] == q['type']:
            return dx**2 + dy**2
        else:
            return dx**2 + dy**2 + abs(dx - dy)

    next_state = []
    for p in state:
        # Find nearest particle of different type
        min_dist = float('inf')
        nearest = None
        for q in state:
            if q is p:
                continue
            if q['type'] != p['type']:
                d = krelon_dist(p, q)
                if d < min_dist:
                    min_dist = d
                    nearest = q

        if nearest is None:
            # No different type, stay
            next_state.append(dict(p))
        else:
            dx = toroidal_diff(p['x'], nearest['x'])
            dy = toroidal_diff(p['y'], nearest['y'])
            sx, sy = sign(dx), sign(dy)

            if p['type'] == 'VEXON':
                # VEXON uses negative sign
                nx = (p['x'] - sx) % 8
                ny = (p['y'] - sy) % 8
            else:
                nx = (p['x'] + sx) % 8
                ny = (p['y'] + sy) % 8

            next_state.append({'type': p['type'], 'x': nx, 'y': ny})

    return next_state
